{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver arrives at the ruined city gates.",
      "visual_description": "A towering iron gate, twisted and overgrown with vines, stands before the glass diver, whose helmet reflects the shattered skyline.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer unfolds a worn map near the gate.",
      "visual_description": "Mara kneels on a cobblestone, brass compass in hand, tracing a path through ink-stained parchment under a pale sun.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers a warning about a cursed tower.",
      "visual_description": "The lamp's single eye glows amber as it casts a long shadow of the tower onto a broken wall.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts ahead through a collapsed archway.",
      "visual_description": "The small metal fox with a key-wind tail silently pads through rubble, blue eyes scanning.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The glass diver peers into a mirror shard and sees a hidden passage.",
      "visual_description": "Fragments of a shattered mirror lean against a wall; the diver's helmet glints as they study the reflection.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Mara marks the hidden passage on her map.",
      "visual_description": "Ink flows from her pen as she adds a dashed line, compass needle wavering.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The oracle lamp warns of armored patrols near the old barracks.",
      "visual_description": "A flicker of orange light reveals silhouettes of figures in armor moving through a distant courtyard.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The tin fox reports from atop a ruined wall.",
      "visual_description": "The clockwork fox perches on a crumbling parapet, key-wind tail ticking, blue eyes fixed on the patrol.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The glass diver uses a window to bypass the patrol.",
      "visual_description": "The diver presses a hand against a dusty windowpane, which ripples like water as they prepare to swim through.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara consults the sleeping tax collector for directions.",
      "visual_description": "In a dusty alcove, the tax collector snores on a pile of ledgers, papers stuck to sleeves; Mara shakes them gently.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "The oracle lamp illuminates a magic door sealed with runes.",
      "visual_description": "A massive door of dark wood glows with faint runes; the lamp's flame casts dancing light on the symbols.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The glass diver deciphers the runes through a mirror.",
      "visual_description": "The diver holds a hand mirror to reflect the runes backward, revealing a pattern of keys.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The tin fox finds a missing key in a bird's nest.",
      "visual_description": "The metal fox climbs a broken column, delicate paws retrieving a brass key from a nest of twigs.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Mara turns the key in the magic door.",
      "visual_description": "The key clicks into the lock; Mara's ink-stained hand twists it as the runes fade.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "The oracle lamp reveals the final escape bridge beyond the door.",
      "visual_description": "Through the open door, a stone bridge stretches over a chasm, torches burning low on either side.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Armored figures block the bridge entrance.",
      "visual_description": "Shadows of figures with swords and shields loom at the bridge's near end, stepping forward in unison.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The glass diver creates a mirror barrier to delay them.",
      "visual_description": "The diver shatters a pane of glass, fragments floating in the air to form a reflective wall that confuses the armored figures.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 18,
      "caption": "The team escapes across the bridge at dawn.",
      "visual_description": "The glass diver, Mara, the oracle lamp, and tin fox race across the bridge as the sun rises, the city ruins behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

